from app.reports import read_export
print(repr(read_export('q3_summary.csv')[:22]))
for bad in ('../../../../etc/passwd', '/etc/passwd', '..'):
    try:
        read_export(bad)
        print('ESCAPE with', bad)
    except FileNotFoundError:
        print('blocked:', bad)
